arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --primary: #003B95;
  --accent: #006CE4;
  --highlight: #FFB700;
  --bg: #F5F5F5;
  --white: #FFFFFF;
  --text-dark: #1A1A1A;
  --text-light: #595959;
  --border: #E0E0E0;
  --radius: 8px;
  --shadow: 0 2px 8px rgba(0,0,0,0.1);
}

* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Inter', sans-serif; }
body { background: var(--bg); color: var(--text-dark); line-height: 1.5; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }
img { max-width: 100%; height: auto; display: block; object-fit: cover; }
.container { max-width: 1140px; margin: 0 auto; padding: 0 1rem; }

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.5rem 1rem; font-weight: 500; border-radius: 4px; cursor: pointer; border: 1px solid transparent; transition: all 0.2s; text-align: center; }
.btn-primary { background: var(--accent); color: var(--white); }
.btn-primary:hover { background: #0056b3; }
.btn-accent { background: var(--primary); color: var(--white); }
.btn-highlight { background: var(--highlight); color: var(--primary); font-weight: 600; }
.btn-outline { border-color: var(--accent); color: var(--accent); }
.btn-white { background: var(--white); color: var(--accent); }
.btn-outline-white { border-color: var(--white); color: var(--white); }

/* Header */
.header { background: var(--primary); color: var(--white); }
.header-top { padding: 1rem 0; }
.header-top .container { display: flex; justify-content: space-between; align-items: center; }
.logo { font-size: 1.5rem; font-weight: 700; }
.header-actions { display: flex; gap: 0.5rem; }
.header-nav { padding-bottom: 0.5rem; }
.header-nav nav { display: flex; gap: 1rem; overflow-x: auto; scrollbar-width: none; }
.header-nav nav::-webkit-scrollbar { display: none; }
.nav-link { padding: 0.5rem 1rem; border-radius: 20px; color: var(--white); display: flex; align-items: center; gap: 0.5rem; font-weight: 500; white-space: nowrap; }
.nav-link.active, .nav-link:hover { background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.2); }
.nav-link:not(.active) { border: 1px solid transparent; }

/* Hero */
.hero { background: var(--primary); color: var(--white); padding: 4rem 0 6rem; position: relative; }
.hero-title { font-size: 3rem; font-weight: 700; margin-bottom: 0.5rem; }
.hero-subtitle { font-size: 1.25rem; margin-bottom: 2rem; }

/* Search Box */
.search-container { background: var(--highlight); padding: 4px; border-radius: var(--radius); margin-top: -32px; position: relative; z-index: 10; display: flex; gap: 4px; flex-wrap: wrap; box-shadow: var(--shadow); }
.search-field { flex: 1; min-width: 200px; background: var(--white); border-radius: 4px; padding: 0.75rem 1rem; display: flex; align-items: center; gap: 0.5rem; color: var(--text-dark); }
.search-field input, .search-field select { border: none; outline: none; width: 100%; font-size: 1rem; background: transparent; }
.search-btn { font-size: 1.125rem; padding: 0.75rem 2rem; border-radius: 4px; }
.search-options { width: 100%; display: flex; gap: 1rem; padding: 0.5rem 1rem; color: var(--text-dark); align-items: center; }

/* Section */
.section { padding: 3rem 0; }
.section-title { font-size: 1.5rem; font-weight: 700; margin-bottom: 0.25rem; }
.section-subtitle { color: var(--text-light); margin-bottom: 1.5rem; }

/* Badges */
.trust-badges { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1.5rem; margin-top: 1rem; }
.badge-item { display: flex; align-items: flex-start; gap: 1rem; }
.badge-icon { color: var(--accent); font-size: 1.5rem; width: 32px; flex-shrink: 0; }
.badge-content h4 { font-weight: 600; margin-bottom: 0.25rem; }
.badge-content p { color: var(--text-light); font-size: 0.875rem; }

/* Offers */
.offers-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1rem; }
.offer-card { background: var(--white); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); display: flex; flex-direction: column; justify-content: space-between; gap: 1rem; border-left: 4px solid var(--accent); }
.offer-card.gold { border-left-color: var(--highlight); }
.offer-card h3 { font-size: 1.25rem; margin-bottom: 0.5rem; }
.offer-card p { color: var(--text-light); }

/* Property Types */
.tags { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.tag { background: var(--white); border: 1px solid var(--border); padding: 0.5rem 1rem; border-radius: 20px; font-size: 0.875rem; color: var(--text-dark); cursor: pointer; }
.tag:hover { background: #f0f0f0; }

/* Tabs */
.tabs { display: flex; gap: 1rem; overflow-x: auto; margin-bottom: 1rem; border-bottom: 1px solid var(--border); padding-bottom: 0.5rem; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab-btn { background: none; border: none; font-size: 1rem; font-weight: 500; color: var(--text-light); padding: 0.5rem 1rem; cursor: pointer; white-space: nowrap; border-radius: 20px; transition: all 0.2s; display: flex; align-items: center; gap: 0.5rem;}
.tab-btn:hover { background: rgba(0,108,228,0.1); }
.tab-btn.active { color: var(--accent); border: 1px solid var(--accent); background: rgba(0,108,228,0.05); }
.tab-content { display: none; }
.tab-content.active { display: block; animation: fadeIn 0.3s; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

/* Cards Grid */
.cards-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; }
.card { background: var(--white); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); transition: transform 0.2s; cursor: pointer; display: flex; flex-direction: column; }
.card:hover { transform: translateY(-4px); }
.card-img { height: 160px; background: #ddd; position: relative; }
.card-img img { width: 100%; height: 100%; object-fit: cover; }
.card-body { padding: 1rem; flex: 1; display: flex; flex-direction: column; }
.card-title { font-weight: 600; font-size: 1.125rem; margin-bottom: 0.25rem; }
.card-text { color: var(--text-light); font-size: 0.875rem; margin-bottom: 0.5rem; flex: 1; }
.card-price { font-weight: 700; font-size: 1.125rem; }
.card-old-price { text-decoration: line-through; color: var(--text-light); font-size: 0.875rem; font-weight: normal; margin-right: 0.5rem; }
.rating { display: inline-flex; align-items: center; gap: 0.25rem; background: var(--primary); color: var(--white); padding: 0.125rem 0.375rem; border-radius: 4px; font-weight: 600; font-size: 0.875rem; }
.rating-text { font-size: 0.875rem; color: var(--text-light); }

/* Carousel */
.carousel-wrapper { position: relative; }
.carousel { display: flex; gap: 1rem; overflow-x: auto; scroll-snap-type: x mandatory; padding-bottom: 1rem; scrollbar-width: none; }
.carousel::-webkit-scrollbar { display: none; }
.carousel .card { min-width: 250px; scroll-snap-align: start; }
.carousel-btn { position: absolute; top: 40%; transform: translateY(-50%); background: var(--white); border: 1px solid var(--border); width: 40px; height: 40px; border-radius: 50%; box-shadow: var(--shadow); cursor: pointer; z-index: 2; display: flex; align-items: center; justify-content: center; }
.carousel-btn.prev { left: -20px; }
.carousel-btn.next { right: -20px; }

/* List */
.list-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1rem; }
.list-item { display: flex; align-items: center; gap: 1rem; padding: 0.5rem; text-decoration: none; color: inherit; }
.list-item:hover { background: var(--white); border-radius: var(--radius); }
.list-img { width: 60px; height: 60px; border-radius: 8px; background: #ddd; flex-shrink: 0; overflow: hidden; }
.list-content { flex: 1; }
.list-title { font-weight: 600; }
.list-desc { color: var(--text-light); font-size: 0.875rem; }

/* Call to Action */
.cta-box { background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); padding: 2rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; }
.cta-content h2 { font-size: 1.5rem; margin-bottom: 0.5rem; }
.cta-content p { color: var(--text-light); }
.cta-actions { display: flex; gap: 1rem; }

/* Footer */
.footer { background: var(--primary); color: var(--white); padding: 3rem 0 1rem; font-size: 0.875rem; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 2rem; margin-bottom: 2rem; }
.footer-col h4 { font-size: 1rem; margin-bottom: 1rem; color: var(--highlight); font-weight: 600; }
.footer-col ul { display: flex; flex-direction: column; gap: 0.5rem; }
.footer-col a:hover { text-decoration: underline; }
.footer-bottom { text-align: center; padding-top: 1rem; border-top: 1px solid rgba(255,255,255,0.2); margin-top: 2rem; }

/* Accordion */
.accordion { border: 1px solid var(--border); border-radius: var(--radius); background: var(--white); overflow: hidden; }
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-item:last-child { border-bottom: none; }
.accordion-header { width: 100%; text-align: left; padding: 1.25rem; font-weight: 600; font-size: 1rem; background: var(--white); border: none; cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
.accordion-content { padding: 0 1.25rem; max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease; color: var(--text-light); }
.accordion-item.active .accordion-content { padding: 0 1.25rem 1.25rem; max-height: 1000px; }
.accordion-item.active .accordion-header { color: var(--accent); }

/* Utility */
.mb-1 { margin-bottom: 1rem; }
.mb-2 { margin-bottom: 2rem; }
.mt-2 { margin-top: 2rem; }
.text-center { text-align: center; }
.d-flex { display: flex; gap: 0.5rem; }
.align-center { align-items: center; }

/* Companies Grid */
.companies-grid { display: flex; flex-wrap: wrap; gap: 2rem; justify-content: center; align-items: center; padding: 2rem 0; }
.company-logo { font-size: 1.5rem; font-weight: 700; color: #999; }

document.addEventListener('DOMContentLoaded', () => {
  // Tabs functionality
  const initTabs = (containerSelector) => {
    const containers = document.querySelectorAll(containerSelector);
    containers.forEach(container => {
      const btns = container.querySelectorAll('.tab-btn');
      const contents = container.querySelectorAll('.tab-content');

      btns.forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.preventDefault();
          const target = btn.dataset.target;

          btns.forEach(b => b.classList.remove('active'));
          contents.forEach(c => c.classList.remove('active'));

          btn.classList.add('active');
          const targetContent = container.querySelector(target);
          if (targetContent) targetContent.classList.add('active');
        });
      });
    });
  };

  initTabs('.tabs-container');

  // Carousel functionality
  const carousels = document.querySelectorAll('.carousel-wrapper');
  carousels.forEach(wrapper => {
    const carousel = wrapper.querySelector('.carousel');
    const prevBtn = wrapper.querySelector('.prev');
    const nextBtn = wrapper.querySelector('.next');

    if (carousel && prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        carousel.scrollBy({ left: -300, behavior: 'smooth' });
      });
      nextBtn.addEventListener('click', () => {
        carousel.scrollBy({ left: 300, behavior: 'smooth' });
      });
    }
  });

  // Accordion functionality
  const accordions = document.querySelectorAll('.accordion');
  accordions.forEach(acc => {
    const items = acc.querySelectorAll('.accordion-item');
    items.forEach(item => {
      const header = item.querySelector('.accordion-header');
      header.addEventListener('click', () => {
        const isActive = item.classList.contains('active');
        // Close all
        items.forEach(i => i.classList.remove('active'));
        // Open clicked if it wasn't active
        if (!isActive) item.classList.add('active');
      });
    });
  });

  // Forms basic submission handling
  const forms = document.querySelectorAll('form');
  forms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      // Simulating search visually
      const btn = form.querySelector('.search-btn');
      if (btn) {
        const originalText = btn.innerText;
        btn.innerText = 'Searching...';
        setTimeout(() => {
          btn.innerText = originalText;
        }, 1000);
      }
    });
  });
});
